import {criarCapitulosAula} from './explicacoes';
import {expandedCourses,expandedLessons,resolveExpandedLesson} from './deep/index';
import type {CapituloAula} from './explicacoes';
export type Lesson={id:string;track:string;title:string;body:string;capitulos:CapituloAula[];code:string;exercise:string;solution:string;error:string;question:string;options:string[];correct:number;language:string;source:string;level?:string;topics?:string[];environment?:string};
export type Course={id:string;title:string;description:string;icon:string;lessonIds:string[]};
export const courses:Course[]=[];
export const lessons:Lesson[]=[];
type Entry=[id:string,title:string,body:string,code:string,exercise:string,solution:string,error:string,question:string,answer:string,wrong:string,other:string];
function course(id:string,title:string,description:string,icon:string,language:string,source:string,entries:Entry[]){courses.push({id,title,description,icon,lessonIds:entries.map(e=>e[0])});for(const [index,e] of entries.entries()){const correct=lessons.length%3,options=[e[9],e[10]];options.splice(correct,0,e[8]);const base={id:e[0],track:id,title:e[1],body:e[2],code:e[3],exercise:e[4],solution:e[5],error:e[6],question:e[7],language,anterior:entries[index-1]?.[1],proxima:entries[index+1]?.[1]};lessons.push({...base,capitulos:criarCapitulosAula(base),options,correct,source});}}
const mdn='https://developer.mozilla.org/pt-BR/docs/';
course('comecando','Começando','Do primeiro passo ao diagnóstico de um erro.','compass','javascript',mdn+'Learn_web_development',[
 ['programar','Programas, código e instruções','Um programa é uma sequência de instruções executáveis. O código é a forma escrita dessas instruções em uma linguagem. Um algoritmo descreve uma solução em passos, mesmo antes de escolher a linguagem. O computador não deduz intenções: a ordem e os valores precisam ser explícitos. console.log mostra um resultado; ele não muda uma variável por conta própria.',`console.log("Abrir o caderno");\nconsole.log("Escrever uma ideia");\nconsole.log("Experimentar");`,'Escreva três instruções que descrevam preparar um café. Troque a ordem e observe o resultado.','console.log("Aquecer a água");\nconsole.log("Colocar o pó no filtro");\nconsole.log("Despejar a água");','Texto precisa de aspas. Café sem aspas será interpretado como um nome de variável.','O que distingue um algoritmo de um código?','O algoritmo descreve passos; o código os expressa em uma linguagem.','Um algoritmo só existe dentro de um computador.','Código sempre resolve corretamente qualquer entrada.'],
 ['entrada-saida','Entrada, processamento e saída','Entrada é o dado recebido; processamento é a transformação; saída é o resultado observável. Separar esses três momentos ajuda a testar. Aqui a quantidade é uma entrada fixa, que você pode alterar. Depois, um formulário pode fornecer a mesma informação. Preveja o resultado antes de executar e compare sua previsão com o console.',`const quantidade = 3;\nconst preco = 8;\nconst total = quantidade * preco;\nconsole.log(total);`,'Calcule o total de cinco cadernos de 12 reais e mostre o resultado.','const quantidade = 5;\nconst preco = 12;\nconsole.log(quantidade * preco);','Usar "5" e "12" como texto pode provocar conversões inesperadas em outras operações.','Qual é a saída para quantidade 3 e preço 8?','24','38','11'],
 ['passos','Decompor um problema','Resolver um problema grande começa por definir o resultado desejado e dividi-lo em etapas pequenas. Para calcular uma média, primeiro identifique as notas, depois some e finalmente divida pela quantidade. Teste cada etapa separadamente. Comentários registram a intenção, mas não executam cálculos. Nomes que descrevem o domínio ajudam a revisar a lógica.',`const primeira = 7;\nconst segunda = 9;\nconst soma = primeira + segunda;\nconst media = soma / 2;\nconsole.log(media);`,'Inclua uma terceira nota 5 e calcule a média das três notas.','const notas = [7, 9, 5];\nconst soma = notas[0] + notas[1] + notas[2];\nconsole.log(soma / notas.length);','Ao acrescentar uma entrada, revise também a quantidade usada como divisor.','Qual passo vem antes de dividir para achar a média?','Somar as notas e contar quantas existem.','Ordenar os nomes dos estudantes.','Converter todas as notas em texto.'],
 ['tipos-erros','Sintaxe, execução e lógica','Um erro de sintaxe impede a leitura do programa, como uma aspa sem par. Um erro durante a execução ocorre quando uma instrução válida encontra uma condição impossível, como usar um nome inexistente. Um erro lógico produz uma resposta inadequada sem necessariamente lançar exceção. Classificar o erro reduz o espaço de investigação.',`const base = 4;\nconst altura = 3;\nconsole.log(base + altura); // Queremos a área!`,'O programa quer calcular a área de um retângulo. Corrija a operação e teste com 4 por 3 e 2 por 5.','const area = (base, altura) => base * altura;\nconsole.log(area(4, 3)); // 12\nconsole.log(area(2, 5)); // 10','Um programa terminar sem erro não significa que respondeu à pergunta correta.','Trocar multiplicação por soma neste cálculo é qual erro?','Lógico.','Obrigatoriamente sintático.','Um erro de rede.'],
 ['investigar','Ler mensagens e investigar','Comece pela primeira mensagem de erro, pelo nome e pela linha indicada. Reduza o código até obter um exemplo pequeno que ainda falha. Observe entradas, valores intermediários e resultado. Faça uma alteração por vez e repita o teste. Ao pedir ajuda, informe resultado esperado e observado; isso é mais útil que dizer apenas que não funciona.',`function dobro(valor) {\n  return valor * 2;\n}\nconsole.log(dobro(0));\nconsole.log(dobro(4));`,'Defina três casos de teste para dobro: zero, positivo e negativo. Explique o resultado esperado.','console.log(dobro(0) === 0);\nconsole.log(dobro(4) === 8);\nconsole.log(dobro(-3) === -6);','Modificar várias partes ao mesmo tempo pode esconder a origem da correção ou criar novos defeitos.','Por que testar também zero?','Porque é um caso de fronteira que pode revelar suposições incorretas.','Porque só zero pode ser usado em testes.','Porque elimina a necessidade de testar outros valores.']
]);
course('logica','Lógica','Valores, decisões, repetição e pequenas funções.','sprout','javascript',mdn+'Web/JavaScript/Guide',[
 ['valores','Valores, tipos e variáveis','Números permitem cálculo; strings representam texto; booleanos representam verdadeiro ou falso. let permite reatribuir um valor e const impede reatribuição do nome. const não congela objetos. Escolha nomes que expressem o papel do dado. Uma variável sem valor inicial recebe undefined, que não equivale ao número zero.',`let energia = 40;\nenergia = energia + 10;\nconst nome = "Lia";\nconst pronto = energia >= 50;\nconsole.log(nome, pronto);`,'Comece com 30 de energia, acrescente 25 e informe se há ao menos 50.','let energia = 30;\nenergia += 25;\nconsole.log(energia >= 50);','Reatribuir um nome declarado com const causa erro. Alterar uma propriedade do objeto é outra operação.','Qual expressão produz um booleano?','energia >= 50','"energia"','50 + 20'],
 ['decisoes','Operadores, comparações e decisões','=== compara sem converter tipos; && exige duas condições e || aceita uma delas. if escolhe um caminho, else trata a alternativa. switch compara um valor com casos definidos; break evita continuar no caso seguinte. Defina primeiro as fronteiras: uma pessoa com exatamente 18 anos atende a idade >= 18.',`function acesso(idade, ingresso) {\n  if (idade >= 18 && ingresso) return "entrar";\n  return "aguardar";\n}\nconsole.log(acesso(18, true));`,'Classifique energia: menor que 20 é baixa, de 20 a 79 é média, 80 ou mais é alta.','function nivel(energia) {\n if (energia < 20) return "baixa";\n if (energia < 80) return "média";\n return "alta";\n}\nconsole.log(nivel(20), nivel(80));','Usar = no lugar de === faz atribuição, não comparação.','Qual valor pertence à faixa média do exercício?','20','19','80'],
 ['repeticoes','Loops e condições de parada','for reúne início, condição e avanço. while repete enquanto uma condição for verdadeira. A condição precisa caminhar para false. Para visitar um array de tamanho n, os índices válidos vão de 0 a n - 1. Evite alterar a coleção que está sendo percorrida sem planejar o efeito nos índices.',`for (let i = 0; i < 3; i++) {\n  console.log("Árvore", i + 1);\n}`,'Some os números de 1 até n. Verifique n igual a 0, 1 e 4.','function somarAte(n) {\n let total = 0;\n for (let i = 1; i <= n; i++) total += i;\n return total;\n}\nconsole.log(somarAte(0), somarAte(1), somarAte(4));','i <= lista.length tenta acessar uma posição após o último item.','Quantas vezes executa um loop com i=0; i<3; i++?','3','4','2'],
 ['funcoes','Funções, parâmetros, retorno e escopo','Uma função descreve uma transformação reutilizável. Parâmetros são nomes de entradas; argumentos são os valores passados na chamada. return entrega um resultado e encerra a função. Uma variável declarada com let dentro de um bloco só existe naquele bloco. Evitar alterações em variáveis externas facilita testar a função isoladamente.',`function desconto(preco, percentual) {\n  const reducao = preco * percentual / 100;\n  return preco - reducao;\n}\nconsole.log(desconto(80, 25));`,'Crie uma função que converta minutos em segundos. Chame-a com 0 e 3.','function segundos(minutos) { return minutos * 60; }\nconsole.log(segundos(0), segundos(3));','console.log mostra um valor; não substitui return quando outro cálculo precisa recebê-lo.','O que return faz?','Entrega o resultado e encerra a chamada.','Repete a função indefinidamente.','Torna toda variável global.'],
 ['colecoes','Arrays, objetos e algoritmos','Arrays organizam sequências; objetos agrupam propriedades nomeadas. Um inventário pode ser um array de objetos com nome e quantidade. Um algoritmo de busca visita itens até encontrar o desejado. Uma acumulação combina vários valores em um total. Antes de otimizar, resolva corretamente coleção vazia, um item e valores repetidos.',`const itens = [{nome:"semente", quantidade:3}, {nome:"água", quantidade:2}];\nlet total = 0;\nfor (const item of itens) total += item.quantidade;\nconsole.log(total);`,'Crie totalEstoque(itens) e teste também com uma lista vazia.','function totalEstoque(itens) {\n let total = 0;\n for (const item of itens) total += item.quantidade;\n return total;\n}\nconsole.log(totalEstoque([]));','Começar o total com undefined faz as somas produzirem NaN.','Qual estrutura representa melhor nome e quantidade de um produto?','Um objeto com propriedades nome e quantidade.','Um número sem propriedades.','Uma condição if sem dados.']
]);
course('javascript','JavaScript','Coleções, composição, erros e assincronismo.','braces','javascript',mdn+'Web/JavaScript/Guide',[
 ['strings-numbers','Strings, números e conversões','Strings são sequências de caracteres e não mudam quando um método devolve outra string. trim remove espaços das pontas; toLowerCase facilita comparação. Number converte texto numérico e pode resultar em NaN. Valide entradas antes de calcular; uma string vazia vira zero com Number, o que pode não ser válido para seu formulário.',`const entrada = " 12 ";\nconst numero = Number(entrada.trim());\nconsole.log(Number.isFinite(numero), numero + 3);`,'Crie uma função que rejeite texto vazio e retorne o dobro de um número válido.','function dobroTexto(texto) {\n if (!texto.trim()) throw new Error("Informe um número");\n const n = Number(texto);\n if (!Number.isFinite(n)) throw new Error("Número inválido");\n return n * 2;\n}\nconsole.log(dobroTexto(" 6 "));','Usar + com uma string pode concatenar: "2" + 3 resulta em "23".','O que Number("abc") produz?','NaN','0','"abc"'],
 ['array-metodos','Arrays, callbacks e transformação','map devolve um array transformado, filter seleciona itens e reduce acumula um resultado. Cada método recebe uma função callback. A callback de filter deve devolver algo interpretável como booleano. Métodos como sort alteram o array original; copie com [...lista] quando precisa preservar a entrada. Teste também arrays vazios.',`const precos = [5, 20, 12];\nconst escolhidos = precos.filter(p => p >= 10);\nconsole.log(escolhidos.map(p => p * 2));`,'Some os valores pares de [1,2,3,4] usando filter e reduce.','const total = [1,2,3,4].filter(n => n % 2 === 0).reduce((soma,n) => soma + n, 0);\nconsole.log(total);','Uma callback com chaves precisa de return explícito, exceto quando só realiza efeitos.','Que método mantém apenas itens que passam numa condição?','filter','map','join'],
 ['objetos-modulos','Objetos, destructuring e módulos','Destructuring extrai propriedades e pode fornecer valores padrão. Spread copia propriedades apenas no primeiro nível: objetos internos continuam compartilhados. Um módulo exporta recursos e outro os importa por caminho. Módulos de navegador precisam de um servidor HTTP e script type="module". O interpretador isolado do laboratório não carrega arquivos externos.',`const pessoa = { nome: "Lia", cidade: "Recife" };\nconst { nome, pontos = 0 } = pessoa;\nconst atualizada = { ...pessoa, cidade: "Natal" };\nconsole.log(nome, pontos, atualizada.cidade);\n// Em soma.js: export const soma = (a,b) => a+b;\n// Em app.js: import { soma } from './soma.js';`,'Copie pessoa mudando apenas o nome e confirme que pessoa.nome continua Lia.','const pessoa = {nome:"Lia",cidade:"Recife"};\nconst copia = {...pessoa,nome:"Bia"};\nconsole.log(pessoa.nome === "Lia", copia.nome === "Bia");','Spread não faz cópia profunda; alterar copia.endereco.rua pode alterar o original.','Qual é a função de export?','Disponibilizar um recurso para outros módulos.','Salvar automaticamente no banco.','Converter um objeto em JSON.'],
 ['erros-json','Exceções, JSON e contratos','JSON representa dados, não funções. JSON.parse pode lançar SyntaxError quando o texto não é válido. try/catch trata uma falha esperada no ponto em que há uma resposta útil. Depois do parse, confira a estrutura: um JSON válido pode conter o tipo errado. Não o injete como HTML; texto de usuário deve ser exibido como texto.',`function lerNome(texto) {\n const dado = JSON.parse(texto);\n if (!dado || typeof dado.nome !== "string") throw new Error("Nome ausente");\n return dado.nome;\n}\ntry { console.log(lerNome('{"nome":"Lia"}')); } catch (erro) { console.log(erro.message); }`,'Teste lerNome com JSON quebrado, null e um objeto válido. Explique as diferenças.','try { console.log(lerNome("null")); } catch (erro) { console.log(erro.message); }\n// null é JSON válido, mas não atende ao contrato.','Capturar tudo e ignorar o erro esconde falhas; apresente um estado ou propague a exceção.','JSON válido garante que os campos necessários existem?','Não; é necessário validar o contrato dos dados.','Sim, JSON valida regras de negócio.','Sim, desde que venha de uma API.'],
 ['async','Promises, async/await e fetch','Promise representa um resultado futuro que pode resolver ou rejeitar. async faz a função retornar uma Promise; await espera a conclusão sem bloquear a interface. fetch rejeita em falhas de rede, mas respostas HTTP como 404 precisam de teste response.ok. Use finally para liberar o estado de carregamento e AbortController para cancelar trabalho desnecessário. Este exemplo de rede deve ser executado no navegador de um projeto servido por HTTP.',`async function carregar(signal) {\n const resposta = await fetch('/api/licoes', {signal});\n if (!resposta.ok) throw new Error('HTTP ' + resposta.status);\n return resposta.json();\n}\n// const controle = new AbortController();\n// carregar(controle.signal).then(console.log).catch(console.error);\n// controle.abort();`,'Descreva quatro estados para uma lista carregada da rede e quando usar cada um.','Inicial antes da consulta; carregando durante a espera; sucesso com dados (ou lista vazia); erro com opção de tentar novamente. Cancelamento por troca de tela não precisa aparecer como falha.','Esquecer await pode tentar acessar dados em uma Promise, antes de estarem disponíveis.','Uma resposta HTTP 404 faz fetch rejeitar automaticamente?','Não; confira response.ok ou status.','Sim, sempre.','Somente se o JSON tiver mais de dez itens.']
]);
course('html','HTML','Estrutura semântica, formulários e acessibilidade.','panels-top-left','html',mdn+'Web/HTML',[
 ['documento','A estrutura de um documento','doctype ativa o modo de padrões. html declara o idioma; head contém metadados; body contém o conteúdo apresentado. charset UTF-8 permite acentos. A meta viewport orienta a largura em dispositivos móveis. title descreve a página na aba e a description resume seu conteúdo. Não use títulos só para aumentar letras: níveis de heading representam organização.',`<!doctype html>\n<html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Meu caderno</title></head><body><h1>Ideias de hoje</h1><p>Uma descoberta por vez.</p></body></html>`,'Acrescente uma description e uma seção com título h2.','No head: <meta name="description" content="Meu caderno de descobertas em programação.">\nNo body: <section><h2>Primeira descoberta</h2><p>HTML organiza conteúdo.</p></section>','Colocar conteúdo visível no head não forma uma estrutura de página correta.','Onde fica o título da aba?','No elemento title dentro de head.','Num atributo alt de qualquer imagem.','Dentro de style.'],
 ['semantica','Semântica, navegação e links','header, nav, main, article e footer comunicam o papel das regiões. Use um main para o conteúdo principal da página. Links navegam; botões executam ações. O texto do link deve dizer para onde vai. Um link de pular navegação permite ao teclado chegar rapidamente ao conteúdo. Semântica nativa reduz a quantidade de ARIA necessária.',`<a href="#conteudo">Pular para o conteúdo</a>\n<header><nav aria-label="Principal"><a href="#sobre">Sobre</a></nav></header>\n<main id="conteudo"><h1>Meu projeto</h1><section id="sobre"><h2>Sobre</h2><p>Aprendendo HTML.</p></section></main>\n<footer>Feito por mim</footer>`,'Adicione um botão que altere seu próprio texto e um link para uma seção.','<button onclick="this.textContent=\'Concluído\'">Concluir tarefa</button>\n<a href="#sobre">Ler sobre o projeto</a>','Uma div com click não recebe automaticamente as interações de teclado de um button.','Qual elemento deve executar a ação salvar?','button','a sem destino','span sem teclado'],
 ['formularios','Formulários, labels e validação','Um label associado pelo for ao id identifica o campo para leitores de tela e amplia a área clicável. name define a chave enviada. type orienta teclado e validação nativa. required e limites ajudam o usuário, mas um servidor também precisa validar entradas. Um placeholder desaparece enquanto se digita e não substitui um rótulo.',`<form onsubmit="event.preventDefault();this.querySelector('output').textContent='Recebido'">\n<label for="nome">Seu nome</label><input id="nome" name="nome" required maxlength="40">\n<label for="email">E-mail</label><input id="email" name="email" type="email" required>\n<button>Enviar</button><output aria-live="polite"></output></form>`,'Inclua um campo de quantidade entre 1 e 10. Teste valores vazio, zero e 5.','<label for="quantidade">Quantidade</label><input id="quantidade" name="quantidade" type="number" min="1" max="10" required>','Validar só no navegador não protege uma API de requisições feitas por outros clientes.','O placeholder substitui o label?','Não; mantenha um rótulo associado ao campo.','Sim, sempre.','Sim, quando o campo é required.'],
 ['imagens-tabelas','Imagens e tabelas de dados','alt descreve a informação transmitida por uma imagem; em imagens decorativas, use alt vazio. Dimensões reservam espaço e reduzem saltos durante o carregamento. Tabelas representam relações de dados com caption, th e scope; não são uma ferramenta geral de layout. Em telas estreitas, permita rolagem na região da tabela sem forçar a página inteira.',`<div style="overflow:auto"><table><caption>Prática semanal</caption><thead><tr><th scope="col">Dia</th><th scope="col">Minutos</th></tr></thead><tbody><tr><th scope="row">Segunda</th><td>20</td></tr></tbody></table></div>`,'Adicione terça-feira com 30 minutos. Descreva o alt de uma imagem que mostra um gráfico desses dados.','<tr><th scope="row">Terça</th><td>30</td></tr>\nAlt possível: Tempo de prática: segunda 20 minutos; terça 30 minutos.','Repetir "imagem de" no alt normalmente não acrescenta informação útil.','Qual elemento identifica o título de uma tabela?','caption','placeholder','legend fora de fieldset'],
 ['html-acessivel','Verificar a acessibilidade','Acessibilidade exige testar a experiência: navegue com Tab, ative com Enter ou Espaço, amplie o texto e confira a ordem dos títulos. Não remova o contorno de foco sem reposição visível. Mensagens de resultado podem usar aria-live="polite". Atributos ARIA complementam o HTML, mas não implementam comportamento de teclado sozinhos.',`<style>button:focus-visible,a:focus-visible{outline:3px solid #8a4400;outline-offset:4px}</style>\n<h1>Contador acessível</h1><button onclick="document.querySelector('output').textContent='Uma ação realizada'">Experimentar</button><output aria-live="polite"></output>`,'Sem usar o mouse, chegue ao botão e acione-o. Depois amplie a página a 200%.','Tab deve focar o botão; Enter ou Espaço deve acioná-lo. O foco deve continuar visível e o texto não pode ficar cortado. Corrija qualquer bloqueio observado.','aria-label em todos os elementos pode substituir nomes visíveis úteis e tornar a navegação confusa.','Como verificar se um botão é acessível por teclado?','Focar com Tab e ativar com Enter ou Espaço.','Olhar apenas a cor do botão.','Adicionar role="button" e não testar.']
]);
course('css','CSS','Da cascata aos layouts responsivos.','layers','html',mdn+'Web/CSS',[
 ['cascata','Seletores, cascata e custom properties','CSS resolve conflitos por origem, importância, camada, especificidade e ordem. Em regras equivalentes, a última vence. Classes descrevem grupos reutilizáveis; seletores de id aumentam a especificidade. Custom properties armazenam valores reutilizáveis e participam da cascata. Evite resolver todo conflito com !important: descubra qual regra está vencendo no inspetor.',`<style>:root{--destaque:#996000}.cartao{color:var(--destaque);padding:1rem;border:1px solid currentColor}.cartao{color:#28634a}</style><p class="cartao">Minha primeira regra.</p>`,'Crie dois cartões e altere a cor dos dois por uma custom property.','<style>:root{--cor:#285f72}.cartao{color:var(--cor)}</style><p class="cartao">Um</p><p class="cartao">Dois</p>','Uma regra posterior não vence automaticamente outra de maior especificidade.','Com mesma especificidade e origem, qual regra vence?','A declarada por último.','Sempre a primeira.','A que tiver o seletor mais curto.'],
 ['box-model','Box model, unidades e tipografia','O tamanho de uma caixa combina conteúdo, padding, border e margin. box-sizing:border-box inclui padding e borda na largura declarada. rem acompanha a fonte raiz; % depende do contexto; px representa pixel CSS. line-height sem unidade mantém proporção com a fonte. Uma medida máxima em ch ajuda a evitar linhas longas demais na leitura.',`<style>*{box-sizing:border-box}.texto{width:100%;max-width:60ch;padding:1.5rem;border:2px solid #285f72;font:1rem/1.6 system-ui;margin:auto}</style><article class="texto"><h1>Uma ideia</h1><p>Espaço também organiza a leitura.</p></article>`,'Adicione uma segunda caixa e compare margin com padding usando cores de fundo.','Padding cria espaço dentro da área pintada da caixa. Margin afasta caixas por fora. Use padding:1rem e margin-block:1rem para observar os dois efeitos.','Definir width:100% com padding no content-box pode ultrapassar a largura do contêiner.','O que border-box inclui na largura declarada?','Conteúdo, padding e borda.','A margem de todos os vizinhos.','Somente o texto.'],
 ['flex-position','Flexbox e posicionamento','Flexbox organiza uma dimensão principal. gap cria espaço entre itens; flex-wrap permite novas linhas. min-width:0 deixa um item encolher quando o conteúdo é longo. position:relative mantém a caixa no fluxo e serve de referência; absolute a retira do fluxo; sticky acompanha a rolagem dentro de seus limites. Não use posição absoluta para montar toda uma página.',`<style>.barra{display:flex;gap:1rem;flex-wrap:wrap;align-items:center}.barra input{flex:1;min-width:0}.barra button{padding:.6rem}</style><div class="barra"><label for="busca">Buscar</label><input id="busca"><button>Pesquisar</button></div>`,'Faça dois cartões dividirem uma linha e quebrarem quando houver pouco espaço.','<style>.grupo{display:flex;flex-wrap:wrap;gap:1rem}.grupo>article{flex:1 1 15rem;padding:1rem;border:1px solid}</style><div class="grupo"><article>Primeiro</article><article>Segundo</article></div>','position:fixed pode cobrir conteúdo e foco em telas pequenas. Reserve espaço e teste.','Qual propriedade permite que itens flex mudem de linha?','flex-wrap: wrap','position: absolute','white-space: nowrap'],
 ['grid-responsivo','Grid, responsividade e container queries','Grid organiza linhas e colunas. repeat(auto-fit,minmax(...)) adapta a quantidade de colunas. Media queries respondem ao viewport; container queries respondem ao tamanho de um contêiner declarado. Comece com uma coluna funcional e aumente a complexidade onde houver espaço. Teste larguras entre os pontos de quebra, não apenas dois tamanhos fixos.',`<style>.grade{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,15rem),1fr));gap:1rem}.bloco{container-type:inline-size;border:1px solid;padding:1rem}@container(min-width:22rem){.bloco p{font-size:1.2rem}}</style><div class="grade"><article class="bloco"><h2>Ilha</h2><p>Um cartão adaptável.</p></article><article class="bloco"><h2>Jardim</h2><p>Outro destino.</p></article></div>`,'Reduza a largura do preview e explique quando muda o número de colunas.','Com espaço para duas colunas mínimas mais o gap, aparecem duas colunas. Abaixo disso o Grid mantém uma. A consulta de contêiner ajusta apenas descendentes conforme a largura local.','Usar minmax(400px,1fr) numa tela de 280px cria overflow; permita um mínimo menor.','A que uma container query responde?','Ao tamanho ou estilo consultável de um contêiner.','Sempre à resolução física do monitor.','Ao número de arquivos CSS.'],
 ['animacoes','Animações com movimento reduzido','Uma transição suaviza a passagem entre dois valores; keyframes descrevem etapas de uma animação. Prefira transform e opacity para reduzir trabalho de layout. Respeite prefers-reduced-motion e evite flashes. Animações de fundo devem pausar quando a página está oculta. O objetivo é comunicar uma mudança sem competir com o conteúdo.',`<style>.semente{display:inline-block;transition:transform .25s}.semente:hover{transform:translateY(-4px)}@media(prefers-reduced-motion:reduce){.semente{transition:none}}</style><button class="semente">Uma descoberta</button>`,'Faça um botão mudar a opacidade ao focar e remova a transição com movimento reduzido.','button{transition:opacity .2s} button:focus-visible{opacity:.8} @media(prefers-reduced-motion:reduce){button{transition:none}}','Animar width em muitos elementos força recalcular layout e pode prejudicar a digitação.','Quais propriedades costumam ser boas opções para animar?','transform e opacity','Sempre width e height de toda a página','Quantidade de requisições HTTP']
]);
course('dom','DOM','Uma página que responde às pessoas.','blocks','html',mdn+'Web/API/Document_Object_Model',[
 ['selecionar','Selecionar e alterar elementos','O DOM é a representação da página como objetos. querySelector retorna o primeiro elemento correspondente ou null. textContent altera texto sem interpretá-lo como HTML. classList modifica classes sem substituir todas as existentes. Faça a seleção depois de o elemento existir: coloque o script após o HTML ou use um módulo.',`<h1 id="titulo">Antes</h1><script>const titulo=document.querySelector('#titulo');if(titulo)titulo.textContent='Uma ideia ganha vida';</script>`,'Acrescente um parágrafo e altere seu texto usando uma classe.','<p class="mensagem">Antes</p><script>document.querySelector(".mensagem").textContent="Depois";</script>','Consultar um seletor errado retorna null; acessar uma propriedade em null causa TypeError.','Qual propriedade insere texto sem interpretar tags?','textContent','innerHTML','outerHTML'],
 ['eventos','Eventos e delegação','addEventListener registra uma resposta a uma ação. event.target é o elemento que iniciou o evento; currentTarget é onde o listener está registrado. Eventos podem subir pelos ancestrais. Na delegação, um listener no contêiner identifica qual item foi acionado com closest. Isso evita registrar um novo listener para cada item criado.',`<ul id="lista"><li><button data-id="1">Concluir um</button></li><li><button data-id="2">Concluir dois</button></li></ul><script>document.querySelector('#lista').addEventListener('click',e=>{const botao=e.target.closest('button');if(botao)botao.textContent='Concluído';});</script>`,'Adicione um terceiro botão depois do registro do listener e confirme que ele funciona.','const item=document.createElement("li");item.innerHTML="<button data-id=\"3\">Concluir três</button>";document.querySelector("#lista").append(item);','Adicionar listeners repetidamente em cada render pode executar a mesma ação várias vezes.','Por que delegar um evento ao contêiner?','Para tratar também itens inseridos posteriormente.','Para impedir todo uso do teclado.','Para transformar HTML em JSON.'],
 ['estado-formulario','Formulário, validação e estado','A interface deve refletir um estado explícito. Ao enviar um formulário, preventDefault evita a navegação padrão. Leia os campos, normalize espaços, valide, atualize o estado e então redesenhe apenas o necessário. Mantenha o foco previsível e anuncie o resultado. Não use o texto visual de um botão como única fonte de verdade.',`<form id="form"><label for="nota">Ideia</label><input id="nota" required><button>Guardar</button></form><ul id="notas"></ul><script>const notas=[];document.querySelector('#form').addEventListener('submit',e=>{e.preventDefault();const campo=document.querySelector('#nota');const texto=campo.value.trim();if(!texto)return;notas.push(texto);const li=document.createElement('li');li.textContent=texto;document.querySelector('#notas').append(li);campo.value='';campo.focus();});</script>`,'Exiba uma contagem atualizada de notas e rejeite entradas com apenas espaços.','Após notas.push, atualize um output com notas.length. A guarda if(!texto)return impede a entrada vazia depois de trim.','required sozinho aceita uma string de espaços; aplique também a regra de domínio.','Quando atualizar o estado de uma nota válida?','Depois de normalizar e validar a entrada.','Antes de ler o campo.','Somente quando o navegador fechar.'],
 ['componentes','Componentes e ciclo de vida','Um componente combina estrutura, estado e comportamento. Mesmo sem framework, uma função pode criar elementos e devolver um método de descarte. Ao remover uma tela, remova listeners globais, cancele timers e libere recursos. Listeners presos apenas a nós descartados geralmente podem ser coletados; listeners no window podem manter uma tela inteira viva.',`<div id="raiz"></div><script>function contador(raiz){let valor=0;const b=document.createElement('button');const atualizar=()=>b.textContent='Cliques: '+valor;b.addEventListener('click',()=>{valor++;atualizar();});atualizar();raiz.append(b);return ()=>b.remove();}const desmontar=contador(document.querySelector('#raiz'));</script>`,'Crie dois contadores e verifique se clicar em um altera somente o seu estado.','Chame contador(raiz) duas vezes. Cada chamada tem seu próprio valor no escopo da função; não declare valor fora de contador.','Um setInterval criado por cada montagem continua ativo se não houver clearInterval no descarte.','Qual recurso normalmente precisa de descarte explícito ao sair de uma tela?','Um timer criado para essa tela.','Uma string literal curta sem referências.','O nome de uma classe CSS.'],
 ['armazenamento','Armazenamento local e recuperação','localStorage salva strings por origem e permanece após recarregar. Serialize objetos com JSON.stringify e valide ao ler. Escritas são síncronas: agrupe alterações com debounce para não bloquear cada tecla. O armazenamento pode falhar por cota ou configuração. Ofereça exportação, limite o histórico e não guarde segredos. O preview isolado bloqueia localStorage; teste o exemplo exportado e servido por HTTP.',`const chave = 'notas.v1';\ntry {\n const dados = JSON.parse(localStorage.getItem(chave) || '[]');\n const notas = Array.isArray(dados) ? dados.filter(x => typeof x === 'string').slice(0,100) : [];\n localStorage.setItem(chave, JSON.stringify(notas));\n} catch { console.log('Não foi possível ler ou salvar.'); }`,'Explique como preservar uma jornada antes de limpar os dados do navegador.','Exporte os dados validados para um arquivo JSON. Depois da limpeza, importe esse arquivo com limite de tamanho e validação de formato. Cache local não é backup remoto.','JSON.parse não valida se o conteúdo é um array de notas.','localStorage sincroniza automaticamente dispositivos?','Não; os dados pertencem à origem naquele navegador.','Sim, sempre que há internet.','Sim, sem precisar de exportação.']
]);
course('apis','APIs','Contratos HTTP, estados e limites de rede.','network','javascript',mdn+'Web/HTTP',[
 ['http','HTTP, rotas e códigos de status','Uma requisição HTTP contém método, endereço, headers e às vezes corpo. A resposta contém status, headers e corpo opcional. GET consulta; 200 indica sucesso com resposta; 201 indica criação; 204 não inclui corpo; 400 aponta entrada inválida; 404 indica recurso não encontrado; 500 aponta falha interna. O status orienta o cliente antes de interpretar os dados.',`const resposta = { status: 404, body: { error: 'Lição não encontrada' } };\nconsole.log(resposta.status >= 200 && resposta.status < 300);`,'Defina uma resposta para criar uma nota com id 7 e outra para consultar um id inexistente.','Criação: status 201, header Location: /notas/7 e corpo com a nota. Consulta ausente: status 404 e uma mensagem compreensível.','Não tente response.json() em uma resposta 204 sem corpo.','O que significa 201?','Um recurso foi criado.','O servidor não foi encontrado.','A requisição foi necessariamente rejeitada.'],
 ['metodos','GET, POST, PUT, PATCH e DELETE','GET consulta sem solicitar alteração. POST geralmente cria ou executa uma operação. PUT substitui a representação de um recurso conhecido; PATCH altera parte dela. DELETE solicita remoção. Idempotência significa que repetir a mesma requisição tem o mesmo efeito pretendido no estado, não que todas as respostas são idênticas. Defina contratos explícitos para cada rota.',`const contrato = [\n ['GET', '/notas', 'listar'],\n ['POST', '/notas', 'criar'],\n ['PUT', '/notas/7', 'substituir'],\n ['PATCH', '/notas/7', 'editar título'],\n ['DELETE', '/notas/7', 'remover']\n];\nconsole.log(contrato);`,'Escolha método e rota para marcar somente concluida=true na tarefa 12.','PATCH /tarefas/12 com JSON {"concluida":true}. Valide o campo no servidor e retorne a representação atualizada ou 204.','Usar GET para remover dados permite alterações causadas por pré-carregamentos e robôs.','Qual método costuma atualizar só parte do recurso?','PATCH','GET','HEAD'],
 ['fetch-estados','Fetch, headers e cancelamento','Content-Type informa como interpretar o corpo; Accept informa o formato desejado da resposta. CORS é uma política do navegador, não autenticação. Um cliente robusto distingue carregando, vazio, sucesso e erro. Cancelar uma consulta antiga evita que resultados de uma seleção anterior sobrescrevam a atual. Confira também um identificador de versão antes de atualizar a tela.',`async function obter(url, signal) {\n const r = await fetch(url, {signal, headers:{Accept:'application/json'}});\n if (!r.ok) throw new Error('HTTP ' + r.status);\n return r.json();\n}\n// Use no navegador servido por HTTP; a bancada isolada bloqueia rede.`,'Descreva o que fazer quando o usuário troca de cidade antes de a consulta anterior terminar.','Abortar o AbortController anterior, iniciar uma consulta com nova versão e aplicar a resposta apenas se ela ainda corresponde à cidade atual.','A requisição mais antiga pode terminar por último; a ordem de início não garante a ordem de chegada.','Para que serve AbortController numa busca?','Para cancelar trabalho que deixou de ser necessário.','Para converter qualquer HTTP 500 em sucesso.','Para ignorar a política CORS.'],
 ['identidade-api','Autenticação e autorização: conceitos','Autenticação responde quem é o cliente; autorização decide o que ele pode fazer. Estes conceitos fazem parte do estudo, mas o CODELAB não solicita login. Uma API pública ainda precisa de validação e limites. Tokens secretos pertencem ao servidor; qualquer segredo embutido no JavaScript enviado ao navegador pode ser lido pelo visitante. Cookies e tokens têm diferentes modelos de ameaça.',`function podeEditar(usuario, nota) {\n return Boolean(usuario) && usuario.id === nota.autorId;\n}\nconsole.log(podeEditar({id:1},{autorId:2}));`,'Explique por que esconder um botão não impede alguém de chamar uma API diretamente.','A interface não é uma fronteira de autorização. O servidor deve verificar a permissão em cada operação protegida, independentemente do botão exibido.','Comparar apenas um id enviado pelo próprio cliente não prova a identidade dele.','Qual é a pergunta de autorização?','Este cliente pode realizar esta operação neste recurso?','Qual cor deve ter o botão?','A página tem um formulário de login?'],
 ['limites-cache','Rate limits, cache e recuperação','Rate limits limitam requisições por intervalo e podem responder 429 com Retry-After. Cache reduz trabalho repetido, mas precisa de chave, prazo e limite de tamanho. Em falhas temporárias, tentativas com espera crescente e variação aleatória evitam enxurradas. Nunca repita uma criação cegamente: a primeira tentativa pode ter sido concluída mesmo sem resposta ao cliente.',`function espera(tentativa) {\n return Math.min(30000, 1000 * 2 ** tentativa);\n}\nconsole.log([0,1,2,3].map(espera));`,'Desenhe uma política para clima com cache de cinco minutos e no máximo duas horas de dados antigos.','Reutilizar cache válido, deduplicar chamadas, consultar após cinco minutos. Em falha, mostrar cache da mesma cidade até duas horas com aviso; depois usar ambiente neutro identificado como ilustrativo.','Guardar cidades ilimitadas num Map transforma o cache numa fonte de crescimento de memória.','Uma resposta 429 pede normalmente qual comportamento?','Respeitar o limite e aguardar antes de tentar novamente.','Repetir imediatamente milhares de vezes.','Apagar todos os dados locais.']
]);
const csharp='https://learn.microsoft.com/en-us/dotnet/csharp/tour-of-csharp/';
course('csharp','C# e .NET 10','Tipos, coleções, objetos e código assíncrono.','file-code-2','csharp',csharp,[
 ['dotnet','SDK, tipos e primeiro programa','C# é a linguagem; .NET fornece runtime e bibliotecas; o SDK inclui ferramentas de compilação. Crie um projeto com dotnet new console -n MeuPrograma e execute com dotnet run. int representa inteiros; decimal é útil para valores decimais monetários; string representa texto; bool representa condições. var infere o tipo na declaração, sem tornar a variável dinamicamente tipada.',`int quantidade = 3;\ndecimal preco = 12.50m;\nstring produto = "Caderno";\nConsole.WriteLine($"{produto}: {quantidade * preco}");`,'Calcule o preço de quatro itens a 7.25 usando decimal.','decimal preco = 7.25m;\nint quantidade = 4;\nConsole.WriteLine(preco * quantidade); // 29.00','Esquecer o sufixo m num literal decimal pode produzir incompatibilidade com double.','O que var faz em C#?','Pede ao compilador que infira o tipo.','Remove a tipagem da variável.','Converte tudo para string.'],
 ['csharp-controle','Condições, loops e métodos','if e switch selecionam caminhos. foreach percorre coleções; for é útil quando você precisa do índice. Métodos declaram tipos de parâmetros e retorno. Um método que não devolve valor usa void. Procure manter cálculo separado da apresentação no console, para poder testá-lo sem depender de texto visual.',`static int SomarAte(int limite) {\n int total = 0;\n for (int i = 1; i <= limite; i++) total += i;\n return total;\n}\nConsole.WriteLine(SomarAte(4));`,'Crie EhPar(int numero) e teste com 0, 3 e 8.','static bool EhPar(int numero) => numero % 2 == 0;\nConsole.WriteLine(EhPar(0));\nConsole.WriteLine(EhPar(3));\nConsole.WriteLine(EhPar(8));','Divisão entre dois int descarta a parte fracionária; converta antes quando precisa dela.','Qual tipo de retorno representa sim ou não?','bool','void','List<int>'],
 ['csharp-objetos','Classes, objetos, herança e interfaces','Uma classe define estrutura e comportamento; um objeto é uma instância. Construtores estabelecem estado válido. Herança modela uma relação é-um; composição conecta objetos colaboradores. Interfaces expressam um contrato sem exigir a mesma classe base. Prefira uma interface pequena que represente uma necessidade real a uma hierarquia criada apenas para reutilizar poucas linhas.',`var item = new Produto("Caderno", 12m);\nConsole.WriteLine(item.Descrever());\ninterface IDescritivel { string Descrever(); }\nsealed class Produto(string nome, decimal preco) : IDescritivel {\n public string Descrever() => $"{nome}: {preco}";\n}`,'Defina uma interface IForma com Area() e implemente um retângulo.','interface IForma { double Area(); }\nsealed class Retangulo(double largura,double altura) : IForma { public double Area() => largura * altura; }\n// Instancie antes das declarações de tipos em um programa com top-level statements.','Herança não deve representar uma relação tem-um; para isso, use uma propriedade colaboradora.','O que uma interface expressa?','Um contrato que diferentes tipos podem implementar.','Uma cópia automática de todos os objetos.','Um banco de dados embutido.'],
 ['csharp-colecoes','Generics, coleções e LINQ','List<T> mantém uma sequência tipada e Dictionary<TKey,TValue> associa chaves a valores. Generics reutilizam algoritmos preservando tipos. LINQ oferece Where, Select, OrderBy e agregações. Muitas consultas têm execução adiada: só são percorridas quando enumeradas. ToList materializa uma cópia dos resultados, útil quando você precisa de uma fotografia estável.',`var valores = new List<int> { 4, 12, 7, 20 };\nvar maiores = valores.Where(n => n >= 10).Select(n => n * 2).ToList();\nConsole.WriteLine(string.Join(", ", maiores));`,'Agrupe somente valores pares e calcule a soma; teste também uma lista vazia.','var numeros = new List<int>{1,2,3,4};\nConsole.WriteLine(numeros.Where(n => n % 2 == 0).Sum());\nConsole.WriteLine(new List<int>().Sum());','Enumerar repetidamente uma consulta pode repetir trabalho ou observar dados modificados.','Qual operação materializa uma consulta em lista?','ToList()','Where() sempre','Uma interface vazia'],
 ['csharp-async','Exceções, arquivos, async e testes','Use try/catch quando consegue tratar uma falha específica; finally libera recursos independentemente do resultado. using descarta IDisposable. Operações de arquivo assíncronas devolvem Task e podem aceitar CancellationToken. await evita bloquear uma thread durante a espera. Testes devem verificar comportamento: entrada, ação, resultado e casos de erro. Operações de arquivo devem ser testadas num projeto local .NET, fora da bancada remota.',`static int Dividir(int a,int b) {\n if (b == 0) throw new ArgumentException("Divisor zero");\n return a / b;\n}\nif (Dividir(8,2) != 4) throw new Exception("Teste falhou");\ntry { Dividir(1,0); } catch (ArgumentException e) { Console.WriteLine(e.Message); }\n// Em projeto local: await File.WriteAllTextAsync("nota.txt", "Olá", cancellationToken);`,'Escreva um teste para divisor negativo e outro que exija exceção para divisor zero.','Verifique Dividir(8,-2)==-4. Para zero, lance falha se Dividir retornar normalmente e capture apenas ArgumentException como resultado esperado. Em projetos maiores, organize esses casos com dotnet test e um framework de testes.','catch(Exception) vazio faz o programa parecer saudável enquanto perde dados ou falha silenciosamente.','Quando usar await?','Ao aguardar uma operação assíncrona sem bloquear desnecessariamente.','Para tornar qualquer loop de CPU automaticamente paralelo.','Para ignorar todas as exceções.']
]);
const asp='https://learn.microsoft.com/en-us/aspnet/core/fundamentals/minimal-apis?view=aspnetcore-10.0';
course('aspnet','ASP.NET Core','Uma API pequena com contratos claros.','network','text',asp,[
 ['aspnet-projeto','Projeto, Program.cs e rotas','Crie um projeto com dotnet new web -n MinhaApi. Program.cs configura serviços, monta o pipeline e registra endpoints. Minimal APIs permitem rotas diretamente com MapGet e MapPost. Controllers organizam endpoints em classes; ambos usam a infraestrutura ASP.NET Core. Execute com dotnet run e consulte a URL exibida. Estes exemplos precisam de um projeto .NET local.',`var builder = WebApplication.CreateBuilder(args);\nvar app = builder.Build();\napp.MapGet("/saude", () => Results.Ok(new { status = "ok" }));\napp.Run();`,'Adicione GET /dobro/{numero:int} e teste /dobro/5 e /dobro/abc.','app.MapGet("/dobro/{numero:int}", (int numero) => Results.Ok(new { resultado = numero * 2 }));\n// 5 retorna 10; abc não corresponde à rota com restrição int.','Não confunda a porta do servidor com a porta de desenvolvimento do front-end.','Qual arquivo concentra a configuração inicial neste exemplo?','Program.cs','index.html','package-lock.json'],
 ['aspnet-di','Injeção de dependência e serviços','Registre dependências no contêiner e receba-as pelo construtor ou pelo handler. Transient cria uma instância por resolução; scoped normalmente acompanha uma requisição; singleton vive por toda a aplicação. Um singleton não deve capturar um serviço scoped. Extraia regras de negócio para serviços quando isso simplificar responsabilidades e testes, sem criar camadas vazias.',`builder.Services.AddScoped<Calculadora>();\n// Depois de Build:\napp.MapGet("/soma", (int a,int b,Calculadora calc) => calc.Somar(a,b));\n// Ao final do arquivo:\nsealed class Calculadora { public int Somar(int a,int b) => a+b; }`,'Escolha o tempo de vida de um serviço que mantém apenas dados da requisição.','Use scoped. Registre com AddScoped e evite guardá-lo em campos de serviços singleton.','Um estado mutável num singleton é compartilhado entre clientes e precisa de coordenação.','Qual tempo de vida normalmente acompanha uma requisição HTTP?','Scoped','Singleton sempre','Um static sem limite'],
 ['aspnet-dto','DTOs, validação e respostas REST','DTOs definem dados de entrada e saída. Não aceite diretamente toda a entidade persistida: isso permite alterar campos que o cliente não deveria controlar. Valide formato, tamanho e regras de domínio. Retorne erros compreensíveis e status coerentes. Repositórios são úteis quando encapsulam consultas e políticas reais; não precisam envolver toda chamada trivial.',`app.MapPost("/notas", (CriarNota input) => {\n if (string.IsNullOrWhiteSpace(input.Titulo) || input.Titulo.Length > 80)\n  return Results.BadRequest(new { error = "Título de 1 a 80 caracteres" });\n var nota = new { Id = Guid.NewGuid(), Titulo = input.Titulo.Trim() };\n return Results.Created($"/notas/{nota.Id}", nota);\n});\nrecord CriarNota(string Titulo);`,'Explique por que CriarNota não deve receber campos como papelAdministrador ou autorConfiavel do cliente.','O servidor decide privilégios e autoria a partir de contexto confiável. Um DTO limitado evita atribuir campos sensíveis diretamente do corpo.','O exemplo cria uma resposta, mas não persiste dados; implemente armazenamento antes de prometer recuperação posterior.','O que deve acontecer com um título vazio?','Uma resposta de validação, antes de salvar.','Salvar como válido e esperar o cliente corrigir.','Promover o cliente a administrador.'],
 ['aspnet-pipeline','Middleware, logging e configuração','Middleware envolve a execução dos próximos componentes do pipeline. A ordem importa: tratamento global de exceções precisa envolver o código que pode falhar. Logging estruturado usa placeholders para preservar campos consultáveis. Configuração vem de arquivos e ambiente; segredos não pertencem ao repositório. Registre metadados úteis sem escrever senhas, tokens ou código privado nos logs.',`app.Use(async (context, next) => {\n var inicio = System.Diagnostics.Stopwatch.StartNew();\n await next();\n app.Logger.LogInformation("{Method} {Status} em {Elapsed}ms",\n  context.Request.Method, context.Response.StatusCode, inicio.ElapsedMilliseconds);\n});`,'Descreva quais dados ajudam a investigar uma API lenta sem registrar o corpo inteiro da requisição.','Método, rota normalizada, status, duração, identificador de correlação e categoria do erro. Evite tokens e dados pessoais.','Logar uma exceção e devolver seu stack trace ao público pode revelar detalhes internos.','Por que a ordem dos middlewares importa?','Porque cada um envolve ou antecede a execução dos seguintes.','Porque muda a versão do C# usada pelo compilador.','Porque substitui os testes.'],
 ['aspnet-protecao','Autenticação, autorização e limites','Em APIs que possuem usuários, configure autenticação para estabelecer identidade e políticas de autorização para proteger ações. RequireAuthorization aplica a política a endpoints; autenticar não garante acesso a todo recurso. Uma API sem contas ainda exige limites de tamanho, concorrência, tempo e saída. O CODELAB desta edição usa apenas armazenamento local e não precisa dessas contas.',`// Em uma aplicação com autenticação configurada:\n// app.MapDelete("/notas/{id}", ExcluirNota).RequireAuthorization("editar-notas");\n// Também verificar permissão sobre a nota específica dentro da operação.`,'Defina quatro limites para um executor público de código.','Limite de caracteres de entrada, número de trabalhos simultâneos, tempo máximo por trabalho e tamanho da saída. Use isolamento do processo e bloqueio de rede para executar código não confiável.','Autorização baseada apenas em esconder a interface não protege o endpoint.','Uma API sem login ainda precisa de limites?','Sim, para controlar recursos e abuso de chamadas.','Não, visitantes anônimos não consomem recursos.','Não, HTTPS limita automaticamente a memória.']
]);
course('banco','Banco de dados','Modelagem, SQL e integridade dos dados.','database','sql','https://www.sqlite.org/lang.html',[
 ['sql-modelagem','Tabelas, tipos e chaves','Uma tabela agrupa registros com os mesmos campos. A chave primária identifica cada registro; uma chave estrangeira relaciona tabelas. Modele a regra do domínio antes de escrever consultas. NOT NULL exige valor; UNIQUE impede repetição conforme as regras do banco. Em SQLite, habilite foreign_keys em cada conexão para verificar referências. Use um banco de exercício separado, nunca o banco real de uma aplicação.',`PRAGMA foreign_keys = ON;\nCREATE TABLE categorias (id INTEGER PRIMARY KEY, nome TEXT NOT NULL UNIQUE);\nCREATE TABLE notas (id INTEGER PRIMARY KEY, titulo TEXT NOT NULL, categoria_id INTEGER REFERENCES categorias(id));`,'Modele autores e livros, permitindo vários livros por autor.','CREATE TABLE autores(id INTEGER PRIMARY KEY, nome TEXT NOT NULL);\nCREATE TABLE livros(id INTEGER PRIMARY KEY, titulo TEXT NOT NULL, autor_id INTEGER NOT NULL REFERENCES autores(id));','Guardar a lista inteira de livros num campo de texto dificulta consultas e integridade.','Qual chave relaciona um livro ao autor?','A chave estrangeira autor_id.','Um texto livre com todos os autores.','O número de colunas da tabela.'],
 ['sql-crud','SELECT, INSERT, UPDATE e DELETE','INSERT cria registros; SELECT consulta; UPDATE altera; DELETE remove. WHERE define quais linhas participam da operação. Antes de um UPDATE ou DELETE, faça um SELECT com a mesma condição e confira as linhas. ORDER BY define a ordem dos resultados; sem ele, não dependa da ordem observada em um teste. Rode estes comandos em um SQLite local descartável.',`CREATE TABLE tarefas(id INTEGER PRIMARY KEY, titulo TEXT NOT NULL, concluida INTEGER NOT NULL DEFAULT 0);\nINSERT INTO tarefas(titulo) VALUES ('Estudar SQL'), ('Praticar');\nUPDATE tarefas SET concluida=1 WHERE id=1;\nSELECT id,titulo FROM tarefas WHERE concluida=0 ORDER BY id;`,'Escreva a consulta que mostra só as tarefas concluídas e depois remova apenas id 2.','SELECT id,titulo FROM tarefas WHERE concluida=1 ORDER BY id;\nDELETE FROM tarefas WHERE id=2;','Esquecer WHERE num UPDATE altera todas as linhas da tabela.','Qual cláusula limita as linhas que serão alteradas?','WHERE','ORDER BY sozinho','CREATE'],
 ['sql-join','JOIN, agrupamento e agregações','JOIN combina linhas relacionadas. INNER JOIN exige correspondência; LEFT JOIN preserva linhas da esquerda mesmo sem correspondência. COUNT(*) conta linhas; COUNT(coluna) ignora valores NULL. GROUP BY reúne grupos para agregações. WHERE filtra antes do agrupamento e HAVING filtra os grupos resultantes. Duplicações podem vir da cardinalidade da relação, não de um defeito do banco.',`SELECT c.nome, COUNT(n.id) AS quantidade\nFROM categorias c\nLEFT JOIN notas n ON n.categoria_id=c.id\nGROUP BY c.id,c.nome\nORDER BY quantidade DESC;`,'Explique por que COUNT(n.id) mostra zero para uma categoria sem notas, mas COUNT(*) pode mostrar um.','LEFT JOIN preserva a categoria com uma linha cujos campos de nota são NULL. COUNT(n.id) ignora esse NULL; COUNT(*) conta a linha preservada.','Um JOIN sem condição adequada pode produzir uma combinação de todas as linhas.','Qual JOIN preserva a categoria sem notas?','LEFT JOIN partindo de categorias.','INNER JOIN sempre','Um DELETE sem WHERE'],
 ['sql-transacao','Transações e consistência','Uma transação reúne operações que devem ser confirmadas ou desfeitas em conjunto. BEGIN inicia; COMMIT confirma; ROLLBACK desfaz mudanças não confirmadas. Transferir valores exige debitar e creditar como uma única unidade. Valide saldo e confira linhas afetadas dentro da estratégia de concorrência escolhida. Uma transação não corrige automaticamente uma regra de negócio errada.',`CREATE TABLE contas(id INTEGER PRIMARY KEY, saldo INTEGER NOT NULL CHECK(saldo>=0));\nINSERT INTO contas VALUES(1,1000),(2,500);\nBEGIN;\nUPDATE contas SET saldo=saldo-200 WHERE id=1;\nUPDATE contas SET saldo=saldo+200 WHERE id=2;\nCOMMIT;\nSELECT * FROM contas;`,'Em uma cópia do banco, execute a transferência e troque COMMIT por ROLLBACK. Compare os saldos.','Com COMMIT: 800 e 700. Com ROLLBACK partindo da base inicial: 1000 e 500. Repita sempre a partir de uma base conhecida.','Confirmar o débito antes do crédito pode deixar dados inconsistentes se a segunda operação falhar.','O que ROLLBACK faz?','Desfaz mudanças ainda não confirmadas da transação.','Apaga obrigatoriamente todo o banco.','Otimiza todas as consultas.'],
 ['sql-indices','Índices, parâmetros e SQL Injection','Índices aceleram determinadas buscas ao custo de espaço e trabalho nas escritas. Escolha-os a partir das consultas e examine o plano com EXPLAIN QUERY PLAN. Use parâmetros para valores externos: concatenar texto do usuário no SQL mistura dado com comando. Parâmetros não substituem nomes de tabelas; para identificadores dinâmicos, use uma lista permitida controlada pelo programa.',`CREATE INDEX idx_notas_categoria ON notas(categoria_id);\nEXPLAIN QUERY PLAN SELECT * FROM notas WHERE categoria_id=1;\n-- Na biblioteca de acesso, vincule o valor em vez de concatená-lo:\nSELECT id,titulo FROM notas WHERE titulo = $titulo;`,'Explique como consultar um título que contém apóstrofo sem montar SQL por concatenação.','Use uma consulta com parâmetro $titulo e atribua o texto ao parâmetro pelo driver. O driver trata o valor como dado, inclusive apóstrofos.','Criar índice em cada coluna aumenta custo de escrita e não garante que o otimizador os use.','O que impede misturar um valor do usuário com comandos SQL?','Consulta parametrizada com parâmetros vinculados pelo driver.','Esconder o campo no HTML.','Confiar que ninguém digitará aspas.']
]);
course('fullstack','Full stack','Conectar interface, API e dados com testes.','layers','text',asp,[
 ['fullstack-arquitetura','As responsabilidades de cada parte','O navegador apresenta a interface e coleta intenção. A API valida regras e coordena operações. O banco mantém dados e restrições. Defina o contrato entre as partes antes de implementar: formato, campos, limites e erros. Neste CODELAB, progresso e projetos ficam no navegador; uma aplicação full stack de estudo é um projeto separado, que você pode construir localmente.',`Navegador → POST /tarefas {"titulo":"Estudar"}\nAPI → validar título → gravar tarefa\nBanco → id 42\nAPI → 201 + {"id":42,"titulo":"Estudar","concluida":false}\nNavegador → adicionar a tarefa confirmada à lista`,'Distribua entre navegador, API e banco: mostrar erro, impedir título vazio, garantir id único.','Navegador mostra erro e ajuda a validar; API valida de forma autoritativa; banco garante a restrição de chave única. Algumas validações existem em mais de uma camada por finalidades diferentes.','Uma regra que existe só na interface pode ser contornada por outro cliente.','Quem deve validar a entrada recebida diretamente por HTTP?','A API, mesmo que o formulário já valide.','Somente o CSS.','O visitante manualmente.'],
 ['fullstack-integracao','Integração e estados da interface','Uma operação de salvar pode falhar ou demorar. Desabilite apenas ações conflitantes, preserve o texto digitado e indique andamento. Atualização otimista mostra o resultado antes da confirmação, mas exige recuperação em caso de erro. Para começar, espere a confirmação do servidor. Use o id devolvido pela API em operações futuras; não suponha que ele é a posição na lista.',`async function salvar(titulo) {\n const r = await fetch('/tarefas',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({titulo})});\n if (!r.ok) throw new Error('Não foi possível salvar');\n return r.json();\n}\n// Rodar no front-end servido junto da API ou com CORS configurado.`,'Defina o comportamento da interface quando salvar retorna 500.','Manter o texto do campo, encerrar o indicador de carregamento, exibir uma mensagem e permitir nova tentativa. Não afirmar que a tarefa foi salva.','Limpar o formulário antes da confirmação pode perder o texto numa falha de rede.','Quando é seguro exibir um id gerado pela API?','Depois de receber e validar a resposta de sucesso.','Antes de enviar a requisição, usando o tamanho da lista.','Só ao fechar a aba.'],
 ['fullstack-testes','Testes de unidade, integração e jornada','Um teste de unidade verifica uma regra isolada. Um teste de integração verifica fronteiras, como API e banco. Um teste de jornada usa a interface como uma pessoa. Escolha cenários com valor: criação válida, validação, edição, exclusão e falha de rede. Testes que repetem a implementação sem observar comportamento dificilmente encontram regressões.',`Cenário: criar tarefa\nDado: lista vazia em banco temporário\nQuando: enviar título "Estudar"\nEntão: resposta 201 e id válido\nE: GET /tarefas contém a tarefa\nE: a interface a mostra após recarregar`,'Acrescente um cenário para título vazio e outro para duas operações simultâneas.','Título vazio deve receber erro sem criar linha. Em concorrência, confirme ids únicos e uma regra explícita para atualizações conflitantes; não aceite perda silenciosa de dados.','Um teste que verifica apenas status 200 não confirma que os dados foram persistidos.','Qual teste verifica navegador → API → banco?','Um teste de jornada integrado.','Somente um teste de soma.','Uma captura de tela sem interações.'],
 ['fullstack-config','Configuração, deploy e observação','Configuração varia por ambiente; código deve manter o mesmo comportamento. Segredos ficam em variáveis de ambiente do servidor ou num gerenciador apropriado. Rode build, testes e migrações planejadas antes de publicar. Depois, verifique saúde, logs e restauração. Um commit no GitHub não publica automaticamente um site: isso depende do fluxo de hospedagem configurado.',`npm ci\nnpm run build\ndotnet build\n# Definir configuração do ambiente de destino sem versionar segredos.\n# Publicar artefatos, executar migrações planejadas e verificar /saude.`,'Liste o que verificar após uma publicação, incluindo um caso de erro e recuperação.','Página principal, assets, criação/consulta de dados, validação, logs sem segredos e endpoint de saúde. Confirme backups e um procedimento de rollback compatível com a versão do banco.','Um build que passa não prova que URLs, variáveis e serviços do ambiente público estão corretos.','Enviar código ao GitHub garante um site publicado?','Não; é necessário um fluxo de hospedagem configurado.','Sim, qualquer repositório vira um site.','Sim, se o README tiver uma imagem.'],
 ['fullstack-memoria','Memória, desempenho e ciclo de vida','Primeiro meça uma tarefa repetível: abrir editor, digitar, executar, sair e repetir. Observe recursos que deveriam voltar ao patamar inicial. Modelos de editor, listeners globais, workers, buffers gráficos e caches podem reter memória. Limite dados por tamanho e tempo; descarte recursos quando seu dono termina. Uma variação temporária de heap não prova vazamento, pois coleta de lixo é assíncrona.',`function observar(elemento) {\n const observer = new ResizeObserver(() => {});\n observer.observe(elemento);\n const timer = setInterval(() => {}, 5000);\n return () => { observer.disconnect(); clearInterval(timer); };\n}\n// const dispose = observar(elemento);\n// Ao desmontar: dispose();`,'Crie um roteiro de 20 trocas entre laboratório e home e defina quais contagens devem permanecer estáveis.','Deve haver no máximo um editor/modelo ativo na bancada, nenhum modelo após sair, um ciclo gráfico, uma consulta de clima por seleção e nenhum worker de execução depois de concluir ou cancelar. Compare também heap após coleta, sem exigir um valor idêntico a cada amostra.','Aumentar o limite de memória pode apenas adiar a falha de um vazamento.','Qual é a primeira medida ao investigar consumo excessivo?','Reproduzir e medir um fluxo definido antes de alterar recursos.','Adicionar caches ilimitados.','Remover todos os testes.']
]);
course('projetos','Projetos reais','Planejar, construir, testar e compartilhar.','castle','text',mdn+'Learn_web_development',[
 ['projeto-diario','Diário de ideias','Construa uma página com formulário, lista, categorias e busca. Mantenha notas como objetos com id estável, texto e data. Use textContent para texto digitado. Persistência local precisa de versão de formato e recuperação de erro. O preview isolado serve para layout e eventos; valide localStorage no arquivo exportado e servido por HTTP. Divida o trabalho em pequenas entregas que já funcionam.',`Modelo: {id:"n1",texto:"Aprender DOM",categoria:"estudo",criadaEm:"2026-09-22"}\nEtapas: estrutura → inclusão → remoção → busca → persistência → exportação`,'Implemente o diário e teste criar, buscar, apagar, recarregar e importar um arquivo inválido.','Aceite somente texto não vazio com limite definido; gere ids; derive a lista filtrada sem alterar o estado original; proteja JSON.parse com validação. A importação inválida deve manter os dados existentes.','Usar o índice filtrado para remover da lista original pode apagar a nota errada.','Como identificar uma nota para removê-la após filtrar?','Pelo id estável da nota.','Pela posição dela na lista filtrada.','Pela quantidade de letras do título.'],
 ['projeto-tarefas','Organizador de pequenos passos','Cada tarefa possui id, título e concluída. A contagem de pendentes é derivada da coleção, não um número separado que pode sair de sincronia. Ofereça filtros para todas, pendentes e concluídas. Uma ação de conclusão deve funcionar com teclado. Preserve o foco após remover um item e apresente um estado vazio útil.',`const tarefas = [{id:1,titulo:'Estudar',concluida:false},{id:2,titulo:'Praticar',concluida:true}];\nconst pendentes = tarefas.filter(t => !t.concluida).length;\nconsole.log(pendentes);`,'Implemente incluir, concluir, reabrir e remover. Compare o contador após cada ação.','Calcule pendentes com filter sempre que renderizar o estado. Teste zero itens, todos concluídos e alternar o mesmo item duas vezes. Use id para atualizar o item correto.','Manter uma variável contador separada exige atualizar todos os caminhos e pode gerar inconsistência.','Como evitar divergência na contagem de pendentes?','Derivá-la do estado atual das tarefas.','Incrementar sempre em qualquer clique.','Guardar um número fixo no HTML.'],
 ['projeto-clima','Painel de clima com cache','Faça um painel que consulta uma cidade selecionada. Mostre cidade, temperatura, fonte e horário de atualização. Cache válido evita repetição; cache antigo deve estar rotulado. Trocar de cidade cancela a busca anterior. Não solicite localização ao abrir a página: ofereça escolha manual e uma ação explícita de consentimento. Dados ausentes devem aparecer como indisponíveis, sem inventar condições extremas.',`Chave de cache: latitude arredondada + longitude arredondada\nValidade: 5 minutos\nDados antigos: até 2 horas, com aviso\nLimite: 4 locais\nPágina oculta: timer pausado\nTroca de local: abortar consulta anterior`,'Teste chuva, céu limpo, falha de rede, localização negada e retorno à aba após seis minutos.','Cada estado deve ter uma resposta clara. Na volta à aba, faça no máximo uma atualização vencida; não crie um novo intervalo sobre o anterior. Um código comum de chuva não deve gerar relâmpagos.','Copiar previsão futura como se fosse condição atual engana quem usa o painel.','Quando solicitar a localização da pessoa?','Depois de ela acionar explicitamente essa opção.','Automaticamente em toda abertura.','Depois de salvar coordenadas precisas sem avisar.'],
 ['projeto-api','Catálogo com ASP.NET e SQLite','Modele produtos com id, nome e preço; publique consulta, criação, edição e remoção numa API local. Use DTOs, validação e consultas parametrizadas. Crie um banco temporário para os testes. O catálogo completo conecta o front-end à API por contrato e trata os estados de rede. Não acrescente login ao CODELAB para fazer este exercício: ele é um projeto separado.',`GET /produtos → 200 + lista\nPOST /produtos → 201 + produto\nPUT /produtos/{id} → 200 ou 404\nDELETE /produtos/{id} → 204 ou 404\nRegra: nome de 1 a 80 caracteres, preço não negativo`,'Implemente uma fatia completa: criar produto, consultar por id e mostrar na interface.','Comece pela migração da tabela e teste de integração da API. Depois faça o formulário aguardar 201 e consultar o recurso criado. Garanta que preço negativo é rejeitado sem gravar uma linha.','Uma lista em memória demonstra rotas, mas não substitui persistência num catálogo que promete sobreviver a reinícios.','Que teste confirma persistência real?','Criar, reiniciar o serviço e consultar o mesmo produto no banco de teste.','Mostrar uma lista fixa no HTML.','Retornar 200 sem gravar.'],
 ['projeto-entrega','Revisar, documentar e entregar','Antes de compartilhar, execute o projeto num ambiente limpo seguindo seu próprio README. Registre requisitos, comandos, decisões e limitações reais. Teste teclado, celular, erro de rede e dados vazios. Versione fontes e lockfile; não envie node_modules, caches, builds duplicados, arquivos pessoais ou segredos. Um bom portfólio explica um problema concreto e mostra evidência do resultado.',`Checklist de entrega:\n1. Instalar e executar com os comandos documentados.\n2. Concluir a jornada principal.\n3. Verificar erros, teclado e telas pequenas.\n4. Conferir arquivos e segredos antes do commit.\n5. Publicar e verificar o endereço final quando houver hospedagem.`,'Escreva um README com objetivo, instalação, uso, testes e limites do seu projeto.','Inclua versões necessárias, comandos copiáveis, um cenário de uso completo, resultados dos testes realmente executados e dependências externas. Não declare um teste aprovado se ele não pôde ser executado.','Confundir conteúdo planejado com funcionalidade entregue dificulta revisão e manutenção.','O que deve entrar no repositório para reproduzir o projeto?','Código fonte, configuração necessária e lockfile, sem segredos.','Todas as pastas node_modules e caches pessoais.','Somente uma captura de tela.']
]);

// O índice é leve; capítulos das novas trilhas são carregados por linguagem.
courses.push(...expandedCourses);
lessons.push(...expandedLessons);
export async function resolveLesson(id:string):Promise<Lesson|undefined>{
 const lesson=lessons.find(entry=>entry.id===id);
 if(!lesson||lesson.capitulos.length)return lesson;
 const full=await resolveExpandedLesson(id);
 if(full)Object.assign(lesson,full);
 return full?lesson:undefined;
}
